def build_stack(sizes):
    """One layer per consecutive pair: sizes [2, 64, 32, 3] gives three layers."""
    layers = []
    for i in range(len(sizes) - 1):
        layers.append(Layer_Dense(sizes[i + 1], sizes[i]))
    return layers


def forward_stack(layers, X):
    """Pass X through every layer in order and return the output of the last one."""
    for layer in layers:
        layer.forward(X)
    return layers[-1].output

questions.solution:
import numpy as np


class Layer_Dense:

    def __init__(self, n_inputs, n_neurons):
        self.weights = 0.01 * np.random.randn(n_inputs, n_neurons)
        self.biases = np.zeros((1, n_neurons))

    def forward(self, inputs):
        self.output = np.dot(inputs, self.weights) + self.biases


def build_stack(sizes):
    """One layer per consecutive pair: sizes [2, 64, 32, 3] gives three layers."""
    layers = []
    for i in range(len(sizes) - 1):
        # n_inputs is what feeds the layer, n_neurons is what it produces.
        layers.append(Layer_Dense(sizes[i], sizes[i + 1]))
    return layers


def forward_stack(layers, X):
    """Pass X through every layer in order and return the output of the last one."""
    values = X
    for layer in layers:
        layer.forward(values)
        values = layer.output          # the next layer reads this layer's output
    return values
